using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Diagnostics;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioBevelScalingValidation {
 public static void Run(){try{Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-scaling-failure.txt")),e.ToString());EditorApplication.Exit(1);}}
 public static void Validate(){var report=new StringBuilder();foreach(int targetCount in new[]{24000,240000,1000000}){var cube=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var poly);var doc=ScriptableObject.CreateInstance<StudioModelDocument>();GameObject renderObject=null;MeshFilter renderFilter=null;Mesh mesh=null;Material material=null;RenderTexture render=null;try{
 material=new Material(Shader.Find("Hidden/StudioValidationSolid"));render=new RenderTexture(128,128,24);render.Create();
 void Draw(){var previous=RenderTexture.active;RenderTexture.active=render;GL.PushMatrix();GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(Matrix4x4.Ortho(-.85f,.85f,-.85f,.85f,.01f,10));GL.modelview=Matrix4x4.TRS(new Vector3(0,0,3),Quaternion.identity,Vector3.one).inverse;if(!material.SetPass(0))throw new Exception("Cannot render sparse bevel probe");Graphics.DrawMeshNow(renderFilter.sharedMesh,Matrix4x4.Rotate(Quaternion.Euler(20,35,0)));GL.PopMatrix();RenderTexture.active=previous;}
 Color32[] Pixels(){var previous=RenderTexture.active;RenderTexture.active=render;var texture=new Texture2D(128,128,TextureFormat.RGBA32,false);texture.ReadPixels(new Rect(0,0,128,128),0,0);texture.Apply();var values=texture.GetPixels32();Object.DestroyImmediate(texture);RenderTexture.active=previous;return values;}
int count=(int)Math.Ceiling((double)targetCount/cube.vertexCount);var p=cube.vertices;var n=cube.normals;var t=cube.tangents;var uv=cube.uv;var tr=cube.triangles;var points=new Vector3[p.Length*count];var normals=new Vector3[points.Length];var tangents=new Vector4[points.Length];var uvs=new Vector2[points.Length];var triangles=new int[tr.Length*count];var polygons=new int[poly.Length*count];for(int copy=0;copy<count;copy++){int offset=copy*p.Length;var delta=copy==0?Vector3.zero:new Vector3(5+copy%50,(copy/50)%50,copy/2500)*2;for(int i=0;i<p.Length;i++){points[offset+i]=p[i]+delta;normals[offset+i]=n[i];if(t.Length>0)tangents[offset+i]=t[i];uvs[offset+i]=uv[i];}for(int i=0;i<tr.Length;i++)triangles[copy*tr.Length+i]=offset+tr[i];for(int cursor=0;cursor<poly.Length;){int size=poly[cursor+1];polygons[copy*poly.Length+cursor]=poly[cursor];polygons[copy*poly.Length+cursor+1]=size;for(int j=0;j<size;j++)polygons[copy*poly.Length+cursor+2+j]=offset+poly[cursor+2+j];cursor+=size+2;}}mesh=new Mesh{name="Sparse million-vertex bevel probe",indexFormat=IndexFormat.UInt32};mesh.vertices=points;mesh.normals=normals;mesh.uv=uvs;if(t.Length>0)mesh.tangents=tangents;mesh.triangles=triangles;mesh.RecalculateBounds();renderObject=new GameObject("Sparse bevel GPU mirror fixture");renderFilter=renderObject.AddComponent<MeshFilter>();renderFilter.sharedMesh=mesh;doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,cutPolygons=polygons,cutTriangles=triangles});using(var preview=new StudioMeshToolPreview(doc,new[]{0})){var target=preview.Targets[0];var f=target.Topology.Faces[0];var edges=new[]{(f.Vertices[0],f.Vertices[1]),(f.Vertices[1],f.Vertices[2]),(f.Vertices[2],f.Vertices[3])};var stageTimes=new Dictionary<string,List<double>>();long previous=0;bool capture=false;StudioMeshCuts.BevelUploadStage=name=>{long now=Stopwatch.GetTimestamp();if(capture&&!name.EndsWith(".start")){if(!stageTimes.TryGetValue(name,out var list))stageTimes[name]=list=new List<double>();list.Add((now-previous)*1000d/Stopwatch.Frequency);}previous=now;};var times=new List<double>();var computeTimes=new List<double>();var publishTimes=new List<double>();var gpuUploadTimes=new List<double>();Color32[] firstPixels=null;int prefix=0,dynamicCount=0;for(int sample=0;sample<60;sample++){capture=sample>=10;var watch=Stopwatch.StartNew();var result=target.Topology.BevelEdges(target.Work,edges,new StudioMeshCuts.BevelOptions{Width=.25f+sample*.003f,Subdivisions=0,Tension=1});double compute=watch.Elapsed.TotalMilliseconds;target.VertexUpdate=result.VertexUpdate;target.VertexUpdateStart=result.VertexUpdateStart;target.PublishedPositions=result.PublishedPositions;target.IsBevelPreview=true;preview.Publish(true);target.UseGpuPreview(renderFilter);watch.Stop();var uploadWatch=Stopwatch.StartNew();Draw();if(sample==10)firstPixels=Pixels();uploadWatch.Stop();if(sample>=10)gpuUploadTimes.Add(uploadWatch.Elapsed.TotalMilliseconds);prefix=result.VertexUpdateStart;dynamicCount=mesh.vertexCount-prefix;if(sample>=10){if(target.StructureChanged)throw new Exception("Topology changed during sparse width evaluation");times.Add(watch.Elapsed.TotalMilliseconds);computeTimes.Add(compute);publishTimes.Add(watch.Elapsed.TotalMilliseconds-compute);}}times.Sort();computeTimes.Sort();publishTimes.Sort();gpuUploadTimes.Sort();report.AppendLine("render vertices="+points.Length+" changed vertices="+dynamicCount+" median ms="+times[times.Count/2]+" p95 ms="+times[(int)Math.Ceiling(times.Count*.95)-1]+" max ms="+times.Last()+" compute median="+computeTimes[computeTimes.Count/2]+" publication median="+publishTimes[publishTimes.Count/2]+" live native GPU preparation median="+gpuUploadTimes[gpuUploadTimes.Count/2]);StudioMeshCuts.BevelUploadStage=null;foreach(var pair in stageTimes){pair.Value.Sort();report.AppendLine("  "+pair.Key+" median="+pair.Value[pair.Value.Count/2]);}if(renderFilter.sharedMesh==mesh)throw new Exception("Sparse GPU mirror was not attached");if(firstPixels.SequenceEqual(Pixels()))throw new Exception("Million-vertex GPU output did not update during bevel drag");if(target.VertexUpdate!=null){var update=target.VertexUpdate;for(int stream=0;stream<update.Streams.Length;stream++){using(var buffer=target.RenderMesh.GetVertexBuffer(stream)){var actual=new float[update.Streams[stream].Length];buffer.GetData(actual,0,update.Start*update.Strides[stream],actual.Length);if(!actual.SequenceEqual(update.Streams[stream]))throw new Exception("GPU vertex stream differs from CPU patch");}}}report.AppendLine("  GPU attribute readback / rendered width update PASS");preview.Restore();if(renderFilter.sharedMesh!=mesh)throw new Exception("Cancel did not restore original renderer mesh");if(!mesh.vertices.SequenceEqual(points))throw new Exception("Sparse cancel changed source");}}finally{if(renderObject)Object.DestroyImmediate(renderObject);if(render)Object.DestroyImmediate(render);if(material)Object.DestroyImmediate(material);if(mesh)Object.DestroyImmediate(mesh);Object.DestroyImmediate(cube);Object.DestroyImmediate(doc);}GC.Collect();}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-scaling-result.txt")),report.ToString());}
}
